import { contextCompactionService } from '../../../src/services/contextCompaction';
import { llmService } from '../../../src/services/llm';
import { useChatStore } from '../../../src/stores/chatStore';
import { createMessage } from '../../utils/factories';
import type { Message } from '../../../src/types';

jest.mock('../../../src/services/llm', () => ({
  llmService: {
    clearKVCache: jest.fn().mockResolvedValue(undefined),
    getTokenCount: jest.fn().mockImplementation((text: string) =>
      Promise.resolve(Math.ceil(text.length / 4)),
    ),
    getPerformanceSettings: jest.fn().mockReturnValue({ contextLength: 2048 }),
    generateWithMaxTokens: jest.fn().mockResolvedValue('Summary of conversation'),
  },
}));

jest.mock('../../../src/stores/chatStore', () => ({
  useChatStore: {
    getState: jest.fn().mockReturnValue({
      updateCompactionState: jest.fn(),
    }),
  },
}));

const mockedLlmService = llmService as jest.Mocked<typeof llmService>;
const mockedUpdateCompactionState = jest.fn();

/** Mock tokenizer: 10 tokens for 'System', customizable for other text */
function mockTokenCounts(nonSystemTokens = 500) {
  mockedLlmService.getTokenCount.mockImplementation((text: string) =>
    text === 'System' ? Promise.resolve(10) : Promise.resolve(nonSystemTokens),
  );
}

/** Shorthand for compact() with default conversationId and systemPrompt */
function compactWith(messages: Message[], extra?: { previousSummary?: string }) {
  return contextCompactionService.compact({
    conversationId: 'conv-1',
    systemPrompt: 'System',
    allMessages: messages,
    ...extra,
  });
}

beforeEach(() => {
  jest.clearAllMocks();
  mockedLlmService.getTokenCount.mockImplementation((text: string) =>
    Promise.resolve(Math.ceil(text.length / 4)),
  );
  mockedLlmService.getPerformanceSettings.mockReturnValue({ contextLength: 2048 } as any);
  mockedLlmService.generateWithMaxTokens.mockResolvedValue('Summary of conversation');
  mockedUpdateCompactionState.mockClear();
  (useChatStore.getState as jest.Mock).mockReturnValue({
    updateCompactionState: mockedUpdateCompactionState,
  });
});

describe('isContextFullError', () => {
  it.each([
    ['Context is full', true],
    ['Not enough context space', true],
    ['CONTEXT IS FULL', true],
    ['Failed: context is full, cannot continue', true],
    ['context window exceeded', true],
    ['context length exceeded', true],
    ['context is full', true],
  ])('"%s" → %s', (msg, expected) => {
    const input = typeof msg === 'string' ? new Error(msg) : msg;
    expect(contextCompactionService.isContextFullError(input)).toBe(expected);
  });

  it('returns false for unrelated errors', () => {
    expect(contextCompactionService.isContextFullError(new Error('No model loaded'))).toBe(false);
  });

  it('handles string errors', () => {
    expect(contextCompactionService.isContextFullError('context is full')).toBe(true);
  });
});

describe('compact', () => {
  it('clears KV cache before compacting', async () => {
    const messages = [
      createMessage({ role: 'system', content: 'System' }),
      createMessage({ role: 'user', content: 'Hello' }),
    ];

    await compactWith(messages);
    expect(mockedLlmService.clearKVCache).toHaveBeenCalledWith(true);
  });

  it('keeps recent messages that fit within recent token budget', async () => {
    const messages = [
      createMessage({ role: 'system', content: 'System' }),
      createMessage({ role: 'user', content: 'msg 1' }),
      createMessage({ role: 'assistant', content: 'reply 1' }),
      createMessage({ role: 'user', content: 'msg 2' }),
      createMessage({ role: 'assistant', content: 'reply 2' }),
      createMessage({ role: 'user', content: 'latest question' }),
    ];

    const result = await compactWith(messages);

    expect(result[0].role).toBe('system');
    expect(result[0].content).toBe('System');
    expect(result[result.length - 1].content).toBe('latest question');
  });

  it('falls back to trim-only on summarization failure', async () => {
    mockTokenCounts(500);
    mockedLlmService.generateWithMaxTokens.mockRejectedValue(new Error('generation failed'));

    const messages = [
      createMessage({ role: 'system', content: 'System' }),
      createMessage({ role: 'user', content: 'old msg' }),
      createMessage({ role: 'assistant', content: 'old reply' }),
      createMessage({ role: 'user', content: 'latest' }),
    ];

    const result = await compactWith(messages);

    expect(result[0].role).toBe('system');
    expect(result[0].content).toBe('System');
    expect(result.find(m => m.id === 'compaction-summary')).toBeUndefined();
    expect(mockedUpdateCompactionState).not.toHaveBeenCalled();
  });

  it('falls back to char estimate when tokenizer fails', async () => {
    mockedLlmService.getTokenCount.mockRejectedValue(new Error('tokenizer unavailable'));
    mockedLlmService.generateWithMaxTokens.mockRejectedValue(new Error('no tokenizer'));

    const messages = [
      createMessage({ role: 'system', content: 'System' }),
      createMessage({ role: 'user', content: 'Hello' }),
    ];

    const result = await compactWith(messages);
    expect(result.length).toBeGreaterThanOrEqual(2);
  });
});

describe('clearSummary', () => {
  it('clears persisted compaction state from store', () => {
    contextCompactionService.clearSummary('conv-1');

    expect(mockedUpdateCompactionState).toHaveBeenCalledWith('conv-1', undefined, undefined);
  });
});

describe('compacting state', () => {
  it('sets isCompacting during compact flow', async () => {
    const states: boolean[] = [];
    const unsub = contextCompactionService.subscribeCompacting(v => states.push(v));

    await compactWith([createMessage({ role: 'user', content: 'Hello' })]);
    unsub();

    expect(states[0]).toBe(false);
    expect(states).toContain(true);
    expect(states[states.length - 1]).toBe(false);
  });

  it('resets isCompacting even on error', async () => {
    mockedLlmService.clearKVCache.mockRejectedValueOnce(new Error('cache error'));

    const states: boolean[] = [];
    const unsub = contextCompactionService.subscribeCompacting(v => states.push(v));

    try {
      await compactWith([]);
    } catch {
      // expected
    }
    unsub();

    expect(states[states.length - 1]).toBe(false);
  });
});

import { pairingSecretStore } from '../../../pro/sync/pairingSecretStore';
import type { DeviceInfo } from '@offgrid/sync';

/**
 * The device's keychain, faked at the boundary and OUTLIVING a module reset - which is the whole
 * point: a restart is a fresh app over storage that is still there.
 */
const vault = globalThis as { __pairingVault?: string | null };

jest.mock('react-native-keychain', () => ({
  ACCESSIBLE: { AFTER_FIRST_UNLOCK: 'AfterFirstUnlock' },
  setGenericPassword: jest.fn(async (_user: string, password: string) => {
    (globalThis as { __pairingVault?: string | null }).__pairingVault = password;
    return true;
  }),
  getGenericPassword: jest.fn(async () => {
    const stored = (globalThis as { __pairingVault?: string | null })
      .__pairingVault;
    return stored ? { username: 'sync-pairings', password: stored } : false;
  }),
  resetGenericPassword: jest.fn(async () => true),
}));

/**
 * A credential outlives the state the pairing happens to be in.
 *
 * The store used to write the secret only for pairings marked 'trusted', so a device flagged
 * needs_repair had its credential dropped by the very next save. The app came back from a restart
 * with the pairing records intact and no secrets at all - and repair then asked for the pairing code
 * forever, on a phone that had never been uninstalled.
 *
 * Keychain is the device boundary and is faked; everything above it is the real store.
 */
describe('pairing credentials survive a restart', () => {
  const iphone: DeviceInfo = {
    id: 'iphone-1',
    name: 'iPhone',
    platform: 'ios',
    version: '1.0.0',
    host: '192.168.1.20',
    port: 51000,
  };

  beforeEach(() => {
    vault.__pairingVault = null;
    jest.resetModules();
  });

  /**
   * A restart is a fresh module over the same Keychain, which is exactly what the app does on
   * launch - no reset hook in production code just to make a test convenient.
   */
  const restart = async (): Promise<typeof pairingSecretStore> => {
    jest.resetModules();

    const reloaded = require('../../../pro/sync/pairingSecretStore')
      .pairingSecretStore as typeof pairingSecretStore;
    await reloaded.load();
    return reloaded;
  };

  const pair = async (): Promise<void> => {
    await pairingSecretStore.load();
    await pairingSecretStore.beginPairing({
      ...iphone,
      sharedSecret: 'shared-secret-42',
      pairedAt: 1,
    });
    await pairingSecretStore.commitPairing({
      ...iphone,
      sharedSecret: 'shared-secret-42',
      pairedAt: 1,
    });
  };

  it('keeps the secret of a pairing that needs repair, across a restart', async () => {
    await pair();
    expect(pairingSecretStore.get(iphone.id)).toBe('shared-secret-42');

    // The peer did not recognise us once - which is not a reason to destroy what the user proved.
    await pairingSecretStore.markNeedsRepair(iphone);
    const reloaded = await restart();

    expect(reloaded.known(iphone.id)?.state).toBe('needs_repair');
    expect(reloaded.get(iphone.id)).toBe('shared-secret-42');
  });

  it('still has the credential after an ordinary restart', async () => {
    await pair();
    const reloaded = await restart();
    expect(reloaded.get(iphone.id)).toBe('shared-secret-42');
  });
});

/**
 * The chat mic must not look usable when the microphone permission is denied. It shows the
 * unavailable mic, explains why on tap, opens Settings, and becomes a normal mic again when the
 * person allows access and comes back. Mounts the real chat, composer, mic button and Whisper
 * service; only the OS permission, Settings hand-off and AppState are faked, at the native leaf.
 */
import { setupChatScreen } from '../../harness/chatHarness';

jest.mock('@react-navigation/native', () => ({
  useNavigation: () => ({
    navigate: () => {},
    goBack: () => {},
    setOptions: () => {},
    addListener: () => () => {},
  }),
  useRoute: () => require('../../harness/chatHarness').routeHolder,
  useFocusEffect: () => {},
  useIsFocused: () => true,
}));

describe.each(['ios', 'android'] as const)('chat mic with the microphone denied (%s)', platform => {
  it('shows the mic as unavailable, opens Settings, and recovers once access is allowed', async () => {
    const h = await setupChatScreen({ engine: 'llama', platform, whisper: true });
    await h.setupWhisperModel('tiny.en');
    h.boundary.setMicPermission('Denied');
    h.render();
    const view = h.view!;

    const deniedMic = await h.rtl.waitFor(() =>
      view.getByTestId('voice-record-button-mic-denied'),
    );
    expect(view.queryByTestId('voice-record-button')).toBeNull();

    h.rtl.fireEvent.press(deniedMic);
    await h.rtl.waitFor(() => {
      expect(view.getByText('Microphone Access Is Off')).toBeTruthy();
    });
    h.rtl.fireEvent.press(view.getByText('Open Settings'));
    expect(h.boundary.settingsOpenedCount()).toBe(1);

    // The person allows the mic in Settings. Nothing changes until they come back to the app.
    h.boundary.setMicPermission('Granted');
    await h.rtl.act(async () => {
      h.boundary.emitAppStateChange('background');
    });
    expect(view.getByTestId('voice-record-button-mic-denied')).toBeTruthy();
    await h.rtl.act(async () => {
      h.boundary.emitAppStateChange('active');
    });
    await h.rtl.waitFor(() => {
      expect(view.getByTestId('voice-record-button')).toBeTruthy();
      expect(view.queryByTestId('voice-record-button-mic-denied')).toBeNull();
    });
  }, 30000);
});

describe('chat mic after an Android "Don\'t ask again" denial', () => {
  it('turns into the unavailable mic as soon as the request is refused', async () => {
    // Android reads a permanent denial back as Undetermined, so the mic starts out normal.
    const h = await setupChatScreen({ engine: 'llama', platform: 'android', whisper: true });
    await h.setupWhisperModel('tiny.en');
    h.boundary.setMicPermission('Undetermined');
    h.render();
    const view = h.view!;
    await h.rtl.waitFor(() => view.getByTestId('voice-record-button'));

    await h.tapMicOnce();

    await h.rtl.waitFor(() => {
      expect(view.getByTestId('voice-record-button-mic-denied')).toBeTruthy();
    });
    expect(h.boundary.whisper!.realtimeActive()).toBe(false);
  }, 30000);
});

describe('chat mic when the permission cannot be read', () => {
  it('stays a normal mic rather than claiming access is off', async () => {
    const h = await setupChatScreen({ engine: 'llama', platform: 'ios', whisper: true });
    await h.setupWhisperModel('tiny.en');
    h.boundary.setMicPermission('Unreadable');
    h.render();
    const view = h.view!;

    await h.rtl.waitFor(() => view.getByTestId('voice-record-button'));
    expect(view.queryByTestId('voice-record-button-mic-denied')).toBeNull();
  }, 30000);
});
